   "code": "// Suggestion cache: exact hits, plus local filtering from a complete shorter prefix\nconst LIMIT = 5;\nclass SuggestCache {\n  constructor(max = 50) { this.max = max; this.map = new Map(); }\n  get(q) {\n    if (this.map.has(q)) { const v = this.map.get(q); this.map.delete(q); this.map.set(q, v); return v.items; }\n    for (let i = q.length - 1; i > 0; i--) {               // look for a complete shorter prefix\n      const p = this.map.get(q.slice(0, i));\n      if (p && p.complete) return p.items.filter(s => s.startsWith(q));\n    }\n    return null;\n  }\n  set(q, items) {\n    this.map.set(q, { items, complete: items.length < LIMIT });\n    if (this.map.size > this.max) this.map.delete(this.map.keys().next().value);\n  }\n}\n\nconst words = ['react', 'reactive', 'read', 'ready', 'real', 'realm', 'redux', 'refetch'];\nlet requests = 0;\nconst server = q => { requests++; return words.filter(w => w.startsWith(q)).slice(0, LIMIT); };\nconst cache = new SuggestCache();\nfunction suggest(q) { let r = cache.get(q); if (!r) { r = server(q); cache.set(q, r); } return r; }\n\nfor (const q of ['r', 're', 'rea', 'reac', 'react', 'rea', 'red']) console.log(q.padEnd(6), suggest(q).join(', '));\nconsole.log('server requests:', requests, 'for 7 keystrokes');",
