   "code": "// Which rows to render, given variable measured heights\nfunction visibleRange(heights, scrollTop, viewport, overscan = 3) {\n  let offset = 0, start = 0;\n  while (start < heights.length && offset + heights[start] <= scrollTop) offset += heights[start++];\n  const top = offset;                     // where the first visible row begins\n  let end = start;\n  while (end < heights.length && offset < scrollTop + viewport) offset += heights[end++];\n  const s = Math.max(0, start - overscan), e = Math.min(heights.length, end + overscan);\n  let padTop = top; for (let i = s; i < start; i++) padTop -= heights[i];\n  return { start: s, end: e, padTop };\n}\n\nconst heights = Array.from({ length: 2000 }, (_, i) => 300 + (i * 37) % 200);   // posts 300-499 px\nfor (const y of [0, 5000, 400000]) {\n  const r = visibleRange(heights, y, 800);\n  console.log(`scrollTop ${y}: render rows ${r.start}-${r.end - 1} (${r.end - r.start} of 2000), spacer ${r.padTop}px`);\n}",
