   "code": "// Minimal OT for concurrent inserts: transform, apply in both orders, converge\nconst apply = (doc, op) => doc.slice(0, op.pos) + op.text + doc.slice(op.pos);\nfunction transform(op, against) {             // shift op to account for an op applied before it\n  if (against.pos < op.pos || (against.pos === op.pos && against.site < op.site))\n    return { ...op, pos: op.pos + against.text.length };\n  return op;\n}\n\nconst doc = 'abc';\nconst alice = { pos: 1, text: 'X', site: 'alice' };\nconst bob   = { pos: 2, text: 'Y', site: 'bob' };\nconst atAlice = apply(apply(doc, alice), transform(bob, alice));\nconst atBob   = apply(apply(doc, bob), transform(alice, bob));\nconsole.log('Alice sees', atAlice, '| Bob sees', atBob, '| converged:', atAlice === atBob);\n\n// Same position: the site id breaks the tie identically on both sides\nconst a2 = { pos: 1, text: 'A', site: 'alice' }, b2 = { pos: 1, text: 'B', site: 'bob' };\nconsole.log(apply(apply(doc, a2), transform(b2, a2)), apply(apply(doc, b2), transform(a2, b2)));",
