   "code": "// Generate CSS variables (light and dark) from one token source\nconst tokens = {\n  color: {\n    bg:     { light: '#ffffff', dark: '#0f1115' },\n    text:   { light: '#1b1f24', dark: '#e6e8eb' },\n    accent: { light: '#0b5fff', dark: '#5b9bff' },\n  },\n  space: { 1: '4px', 2: '8px', 3: '12px', 4: '16px', 6: '24px' },\n  radius: { sm: '4px', md: '8px' },\n};\nfunction toCss(t) {\n  const lines = { light: [], dark: [], shared: [] };\n  for (const [name, v] of Object.entries(t.color)) { lines.light.push(`--color-${name}: ${v.light};`); lines.dark.push(`--color-${name}: ${v.dark};`); }\n  for (const group of ['space', 'radius']) for (const [k, v] of Object.entries(t[group])) lines.shared.push(`--${group}-${k}: ${v};`);\n  return `:root {\\n  ${[...lines.shared, ...lines.light].join('\\n  ')}\\n}\\n[data-theme=\"dark\"] {\\n  ${lines.dark.join('\\n  ')}\\n}`;\n}\nconsole.log(toCss(tokens));",
